export function HeroSection({
  headline = "{{headline}}",
  subheadline = "{{subheadline}}",
  ctaText = "{{ctaText}}",
  align = "{{align}}",
  bg = "{{bg}}",
}) {
  const centered = align === "center";
  return (
    <section style={{ font: "16px/1.5 system-ui, sans-serif", color: "#FAF7F2", padding: "72px 32px",
      borderRadius: 16, textAlign: align, background: bg }}>
      <h1 style={{ margin: centered ? "0 auto 16px" : "0 0 16px", fontSize: 40, fontWeight: 800, maxWidth: "18ch" }}>{headline}</h1>
      <p style={{ margin: centered ? "0 auto 28px" : "0 0 28px", fontSize: 17, opacity: 0.85, maxWidth: "46ch" }}>{subheadline}</p>
      <button type="button" style={{ background: "#FAF7F2", border: "none", padding: "14px 30px", borderRadius: 10,
        fontWeight: 700, fontSize: 15, cursor: "pointer", color: bg }}>{ctaText}</button>
    </section>
  );
}
